import java.nio.file.Paths;

/**
 * Cloud-ready file reading utility that supports both classpath resources and file paths.
 * This replaces the desktop-based JFileChooser with cloud-compatible alternatives.
 */
public class ReadDataUtils {

    private static final Logger log = LoggerFactory.getLogger(ReadDataUtils.class);

    /**
     * Read file from a given path or classpath resource.
     * In cloud environments, files should be provided via:
     * - Environment variables pointing to S3/cloud storage paths
     * - Classpath resources bundled with the application
     * - Mounted volumes in container environments
     *
     * @param filePath The file path or classpath resource location
     * @return File object if found, null otherwise
     */
    public static File readFile(String filePath) {
        if (filePath == null || filePath.isEmpty()) {
            log.warn("File path is null or empty");
            return null;
        }

        try {
            Path path = Paths.get(filePath);
            File file = path.toFile();

            if (file.exists() && file.canRead()) {
                log.info("Successfully located file: {}", filePath);
                return file;
            } else {
                log.warn("File not found or not readable: {}", filePath);
                return null;
            }
        } catch (Exception e) {
            log.error("Error reading file: {}", filePath, e);
            return null;
        }
    }

    /**
     * Read file from classpath resource - useful for cloud deployments
     * where files are packaged with the application.
     *
     * @param resourceLoader Spring ResourceLoader
     * @param resourcePath Classpath resource path (e.g., "classpath:data/file.csv")
     * @return Resource object
     */
    public static Resource readClasspathResource(ResourceLoader resourceLoader, String resourcePath) {
        try {
            Resource resource = resourceLoader.getResource(resourcePath);
            if (resource.exists()) {
                log.info("Successfully located classpath resource: {}", resourcePath);
                return resource;
            } else {
                log.warn("Classpath resource not found: {}", resourcePath);
                return null;
            }
        } catch (Exception e) {
            log.error("Error reading classpath resource: {}", resourcePath, e);
            return null;
        }
    }

}

