import java.util.List;

/**
 * CSV Test utility - Cloud-ready version with proper logging and error handling.
 * For cloud deployments, CSV files should be:
 * - Uploaded to S3/cloud storage and downloaded at runtime
 * - Provided via environment variables pointing to cloud storage paths
 * - Packaged as classpath resources for static data
 */
public class CSVTest {

    private static final Logger log = LoggerFactory.getLogger(CSVTest.class);

    public static void main(String[] args) {
        // In cloud environment, file path should come from environment variable
        String csvFilePath = System.getenv("CSV_FILE_PATH");
        if (csvFilePath == null || csvFilePath.isEmpty()) {
            log.error("CSV_FILE_PATH environment variable not set. Please configure file path.");
            return;
        }

        File document = ReadDataUtils.readFile(csvFilePath);
        if (document == null) {
            log.error("Failed to read CSV file from path: {}", csvFilePath);
            return;
        }

        log.info("Processing CSV file: {}", document.getName());

        CSVReader reader = null;
        List<Object[]> data = new ArrayList<>();
        try {
            reader = new CSVReader(new FileReader(document));
            String[] line;
            int lineNumber = 0;
            while ((line = reader.readNext()) != null) {
                lineNumber++;
                data.add(line);
                if (line.length > 1 && "QUICK SUB".equals(line[1])) {
                    log.info("Found QUICK SUB at line {}: {} | {} | {}",
                            lineNumber, line[0], line[1], line.length > 2 ? line[2] : "N/A");
                }
            }
            log.info("Successfully processed {} lines from CSV file", lineNumber);
        } catch (IOException e) {
            log.error("Error reading CSV file: {}", document.getName(), e);
        } finally {
            if (reader != null) {
                try {
                    reader.close();
                } catch (IOException e) {
                    log.error("Error closing CSV reader", e);
                }
            }
        }
    }

}

